from core import *

@register('limits','dyadic-log-product','geometrically-spaced-product-critical-scale','moving-cutoff-and-uniform-log-remainder','An infinite product has a quadratic logarithmic divergence. The cutoff moves with the small parameter, and both the pre-cutoff approximation error and infinite tail need uniform bounds.','Euler finite-product corrections concern smooth fixed-scale factors; here the number of small factors grows logarithmically.',[{'caseId':'base-'+str(b),'b':b,'purpose':'Different geometric scales with a changing cutoff phase.'} for b in range(2,10)],['infinite products','logarithms','geometric sums','asymptotic estimates'])
def dyadic(case):
 b=s.Integer(case['b']);A=-1/(2*s.log(b));K=s.symbols('K',integer=True,positive=True);Lvar=s.symbols('L',positive=True)
 ck('The exact pre-cutoff logarithmic sum',s.summation(-Lvar+k*s.log(b),(k,0,K)),-(K+1)*Lvar+K*(K+1)*s.log(b)/2)
 ck('Substitution of the leading cutoff scale produces the quadratic coefficient',s.expand((-(Lvar/s.log(b)+1)*Lvar+(Lvar/s.log(b))*(Lvar/s.log(b)+1)*s.log(b)/2)).coeff(Lvar,2),A)
 analytic('Uniform cutoff bounds',['The base is an integer greater than one, and t decreases to zero through positive reals. The infinite product is taken in increasing index order.'],['For each t>0, the sum of exp(-t b^k) converges, so the product is positive and its real logarithm is the sum of logarithms.','Let L=ln(1/t), K=floor(L/ln b). For0<=k<=K, u=t b^k<=1 and ln(1-exp(-u))=ln u+O(u), with a uniform constant; sum u is bounded independently of t.','For k>K, t b^k>b^(k-K-1). The logarithmic tail is bounded absolutely by a convergent base-dependent series, uniformly in t.','The main sum is -(K+1)L+K(K+1)ln b/2. Since K=L/ln b+O(1), divide by L^2 to obtain the result.'])
 return candidate(r'P(t)=\prod_{k=0}^{\infty}(1-e^{-t'+L(b)+r'^k})\quad(t>0).\qquad\lim_{t\downarrow0}\frac{\ln P(t)}{(\ln(1/t))^2}',A,[(2*A,'Omit the triangular half in the sum of logarithmic factor sizes'),(A/2,'Apply the triangular half twice'),(-A,'Reverse the sign of the logarithmic factors'),(-s.log(b)/2,'Multiply by the logarithmic scale instead of dividing'),(-1/(2*s.log(b)**2),'Use the cutoff scale twice'),(s.Integer(0),'Treat the number of small factors as bounded')],[r'L=\ln(1/t),\quad K=\left\lfloor\frac L{\ln '+L(b)+r'}\right\rfloor',r'\ln(1-e^{-u})=\ln u+O(u)\quad(0<u\le1),\qquad\sum_{k=0}^Kt'+L(b)+r'^k=O(1)',T('The remaining factors have arguments bounded below by a growing geometric sequence. Their logarithms form an absolutely bounded tail, uniformly in the small parameter.'),r'\ln P(t)=\sum_{k=0}^K(-L+k\ln '+L(b)+r')+O(1)=-(K+1)L+\frac{K(K+1)}2\ln '+L(b)+r'+O(1)',r'K=\frac L{\ln '+L(b)+r'}+O(1),\qquad\ln P(t)=-\frac{L^2}{2\ln '+L(b)+r'}+O(L)'],'infinite-product-geometric-cutoff-log-square')

@register('limits','lipschitz-mass-concentration','sharp-mass-slope-concentration','cone-under-peak-and-attaining-tent','A small integral norm does not itself control a peak. The slope constraint forces a minimum cone of mass, and boundary geometry changes its sharp coefficient.','A prescribed spike only demonstrates nonuniform convergence; this optimizes over every admissible function and proves a sharp bound.',[{'caseId':'power-'+str(p)+'-'+side,'p':p,'side':side,'purpose':'Change the mass norm and whether one or two sides of a peak are forced.'} for p in [2,3,4,5] for side in ['zero-endpoints','free-endpoints']],['Lipschitz functions','integral bounds','sharp optimization','boundary conditions'])
def lipschitz(case):
 p=case['p'];side=case['side'];sides=2 if side=='zero-endpoints' else 1;A=R(p+1,sides)**R(1,p+1);M=s.symbols('M',positive=True);slope=s.symbols('L',positive=True)
 ck('Independent integral of the forced one-sided cone',s.integrate((M-slope*x)**p,(x,0,M/slope)),M**(p+1)/(slope*(p+1)))
 ck('The constructed optimal height satisfies the exact mass budget',sides*A**(p+1)/(p+1),1)
 analytic('Sharp concentration asymptotic',['Functions are nonnegative on[0,1], Lipschitz constant at most n, and the pth-power integral is at most1/n.','In the zero-endpoint case both endpoint values vanish. In the free case there is no endpoint restriction.'],['At a height M, the slope bound forces f(x)>=max(M-n|x-x0|,0). With zero endpoints the entire two-sided cone fits in[0,1], giving mass at least2M^(p+1)/(n(p+1)).','For free endpoints, if M/n<=1 the truncated cone has minimum integral when its peak lies at an endpoint, giving M^(p+1)/(n(p+1)). If M/n>1, an interval of length1/2 has height at least M-n/2, contradicting the vanishing mass budget for all sufficiently large n.','Thus the displayed constant bounds every peak for large n. A centered tent with zero endpoints, or an endpoint tent in the free case, has that height, slope n, and exactly mass1/n for all sufficiently large n.'])
 bound=r'f(0)=f(1)=0,\quad' if sides==2 else ''
 return candidate(T('For every positive integer n, let ')+r'M_n=\sup\left\{\max_{0\le x\le1}f(x):f\ge0,\quad|f(x)-f(y)|\le n|x-y|,\quad '+bound+r'\int_0^1f(x)^{'+str(p)+r'}\,\mathrm dx\le\frac1n\right\}.'+T('The supremum is over real functions on the unit interval. Find ')+r'\lim_{n\to\infty}M_n.',A,[(s.Integer(p+1)**R(1,p+1),'Use only one side of a peak even when both are required'),(R(p+1,2)**R(1,p+1),'Impose two sides even when an endpoint peak is allowed'),(R(p+1,2*sides)**R(1,p+1),'Count every forced side twice'),(R(2*(p+1),sides)**R(1,p+1),'Halve the forced cone mass'),(R(p,sides)**R(1,p+1),'Use p rather than p plus one in the cone integral'),(R(p+1,sides)**R(1,p),'Use the wrong power when solving the mass equation')],[T('At any maximum, the Lipschitz bound forces a tent-shaped lower envelope.'),r'f(x)\ge\max\{M-n|x-x_0|,0\}\quad\textnormal{if }f(x_0)=M',r'\int_0^{M/n}(M-ns)^{'+str(p)+r'}\,\mathrm ds=\frac{M^{'+str(p+1)+r'}}{'+str(p+1)+r'n}',T('The endpoint conditions force two complete sides.' if sides==2 else 'For a fixed height, truncating a tent at an endpoint minimizes its mass. For all sufficiently large n the admissible peak width is smaller than the interval.'),r'\frac1n\ge\frac{'+str(sides)+r'M^{'+str(p+1)+r'}}{'+str(p+1)+r'n}\quad\Longrightarrow\quad M\le'+L(A),T('A centered tent with zero endpoint values realizes equality for large n.' if sides==2 else 'A tent centered at the left endpoint realizes equality for large n.'),r'M_n='+L(A)+r'\quad\textnormal{for all sufficiently large }n'],'sharp-Lipschitz-integral-mass-peak-concentration')

@register('limits','discrete-volterra-norm','Green-operator-spectrum','inverse-difference-matrix-and-mixed-boundary-spectrum','A quadratic optimization over growing dimension is reduced by inversion to a discrete boundary-value problem; the half-grid endpoint determines the sharp spectral constant.','This is an operator norm with a growing spectrum, not a fixed matrix power or a scalar recurrence.',[{'caseId':'grid-'+str(a)+'-'+str(b),'a':a,'b':b,'purpose':'Different growth scales and boundary offsets; offsets test the mixed-endpoint phase without changing the leading scale.'} for a,b in [(1,0),(1,1),(2,0),(2,1),(3,0),(3,2),(4,1),(5,0)]],['quadratic forms','eigenvalues','difference equations','trigonometric limits'])
def volterra(case):
 a=case['a'];b=case['b'];A=4*s.Integer(a)**2/pi**2
 for N in [2,3,4,5]:
  C=s.Matrix(N,N,lambda i,j:1 if j<=i else 0);B=C.inv();Q=B.T*B
  target=s.diag(*([2]*(N-1)+[1]))
  for i in range(N-1):target[i,i+1]=target[i+1,i]=-1
  ck('Independent inverse cumulative-sum matrix gives the mixed-endpoint tridiagonal form at size '+str(N),Q,target)
  # Symbolic recurrence identities, not numerical eigenvalues.
 theta=pi/(2*n+1);thetaSymbol=s.symbols('theta',real=True);j=s.symbols('j',integer=True)
 ck('The interior sine mode solves the second-difference eigen-equation',s.expand_trig(2*s.sin(j*thetaSymbol)-s.sin((j-1)*thetaSymbol)-s.sin((j+1)*thetaSymbol)),(2-2*s.cos(thetaSymbol))*s.sin(j*thetaSymbol))
 analytic('Exact discrete mixed-boundary spectrum',['The optimizing vector is any nonzero real vector, and the number of coordinates tends to infinity along the displayed affine integer sequence.'],['Let y_j be cumulative sums and y_0=0. The denominator becomes sum(y_j-y_(j-1))^2. Its symmetric matrix has diagonal2 except its final entry1, and adjacent entries-1.','The sine eigenvector y_j=sin(j theta) obeys the left boundary automatically. The last row is equivalent to sin((N+1)theta)=sin(N theta), so theta_l=(2l-1)pi/(2N+1), l=1..N.','These N distinct eigenvalues are2-2cos(theta_l)>0. The smallest is4sin^2(pi/(4N+2)); reciprocal gives the maximum Rayleigh quotient.','With N=an+b, divide by n^2 and use sin u/u->1.'])
 Ntex=str(a)+r'n'+('+'+str(b) if b else '')
 return candidate(r'N_n='+Ntex+r',\qquad V_n=\max_{\mathbf x\in\mathbb R^{N_n}\setminus\{0\}}\frac{\displaystyle\sum_{j=1}^{N_n}\left(\sum_{k=1}^jx_k\right)^2}{\displaystyle\sum_{k=1}^{N_n}x_k^2}.\qquad\lim_{n\to\infty}\frac{V_n}{n^2}',A,[(s.Integer(a)**2/pi**2,'Impose a zero value at the right endpoint instead of the natural difference boundary'),(2*s.Integer(a)**2/pi**2,'Lose the half-angle factor in the eigenvalue'),(8*s.Integer(a)**2/pi**2,'Double the reciprocal eigenvalue'),(16*s.Integer(a)**2/pi**2,'Apply the half-grid correction twice'),(4*s.Integer(a)/pi**2,'Scale the dimension linearly rather than quadratically'),(s.Integer(a)**2/2,'Use the constant vector test as if it optimized the quotient'),(4/(s.Integer(a)**2*pi**2),'Invert the grid-growth factor')],[r'y_j=\sum_{k=1}^jx_k,\quad y_0=0,\qquad\sum_jx_j^2=\sum_{j=1}^{N_n}(y_j-y_{j-1})^2',T('The inverse quotient is the smallest eigenvalue of the tridiagonal difference matrix with final diagonal entry one. Its sine modes satisfy the two boundary conditions below.'),r'y_j=\sin(j\theta),\quad\lambda=2-2\cos\theta,\quad y_0=0,\quad y_{N_n+1}=y_{N_n}',r'\theta_\ell=\frac{(2\ell-1)\pi}{2N_n+1}\quad(1\le\ell\le N_n),\qquad V_n=\frac1{4\sin^2(\pi/(4N_n+2))}',r'\frac{N_n}{n}\longrightarrow'+str(a)+r',\qquad\frac{V_n}{n^2}\longrightarrow\frac{4\cdot'+str(a)+r'^2}{\pi^2}='+L(A)],'growing-cumulative-sum-norm-mixed-boundary-eigenmode')

@register('limits','singular-riemann-renormalization','singular-Riemann-sum-finite-part','endpoint-subtraction-and-integrable-remainder','A divergent endpoint prevents an ordinary Riemann-sum argument; subtracting the singular model exposes both its exact constant and the integrable remainder.','The hyperbola family controls integer floor errors by counting. This construction isolates a nonintegrable endpoint and its finite part.',[{'caseId':'power-'+str(p),'p':p,'purpose':'A different endpoint singularity order with the same finite-part decision.'} for p in [2,3,4,5,6,7,8,9]],['Riemann sums','Euler constant','endpoint asymptotics','harmonic numbers'])
def singular(case):
 p=case['p'];u=s.symbols('u',positive=True);F=(1-u**p)/(1-u);rem=s.cancel(F-p);A=-s.harmonic(p-1)
 # Target sum 1/[k(1+k/n+...)] subtract1/k, integral remainder.
 g=s.cancel((1/(1+u+sum(u**j for j in range(2,p)))-1)/u)
 # Integral is not generally harmonic here; use (1-k/n)^(p-1)/k instead, integral polynomial remainder exactly -H_(p-1).
 g=s.cancel(((1-u)**(p-1)-1)/u)
 ck('The subtracted endpoint quotient is a polynomial',s.rem(s.expand((1-u)**(p-1)-1),u,u),0)
 ck('Independent direct polynomial integration gives the finite-part constant',s.integrate(g,(u,0,1)),A)
 ck('The harmonic expansion of the endpoint integral agrees',s.expand_func(s.integrate(sum(-((1-u)**j) for j in range(p-1)),(u,0,1))),A)
 analytic('Subtract the singular endpoint',['The integer power is positive; all sums use positive integer indices; Euler constant is explicitly defined.'],['Write the sum as H_n plus(1/n)sum g(k/n), where g(u)=((1-u)^(p-1)-1)/u extends continuously to u=0.','The second term is an ordinary Riemann sum for the integral of the polynomial g, equal to minus H_(p-1).','Subtract ln n and use H_n-ln n->gamma.'])
 # This is intentionally hard rather than advanced; do not count routine subtraction as Olympiad.
 answer=s.EulerGamma+A
 return candidate(r'\gamma=\lim_{q\to\infty}\left(\sum_{j=1}^q\frac1j-\ln q\right).\qquad\lim_{n\to\infty}\left(\sum_{k=1}^n\frac{(1-k/n)^{'+str(p-1)+r'}}k-\ln n\right)',answer,[(s.EulerGamma-A,'Reverse the sign of the subtracted remainder'),(s.EulerGamma-s.harmonic(p),'Use the next harmonic number'),(s.EulerGamma-s.harmonic(max(0,p-2)),'Use the previous harmonic number'),(s.EulerGamma,'Discard the finite Riemann remainder'),(A,'Discard the Euler constant'),(s.EulerGamma+2*A,'Count the remainder twice')],[r'g(u)=\frac{(1-u)^{'+str(p-1)+r'}-1}{u}='+L(g),T('This polynomial gives the continuous extension at the otherwise singular endpoint.'),r'\sum_{k=1}^n\frac{(1-k/n)^{'+str(p-1)+r'}}k=H_n+\frac1n\sum_{k=1}^ng(k/n),\qquad H_n=\sum_{k=1}^n\frac1k',r'\frac1n\sum_{k=1}^ng(k/n)\longrightarrow\int_0^1g(u)\,\mathrm du='+L(A),r'H_n-\ln n\longrightarrow\gamma'],'endpoint-subtracted-polynomial-weighted-harmonic-sum')
FAMILIES['q1-limits-olympiad-singular-riemann-renormalization']['difficulty']='hard'
